/** One list: action => [HTTP method, handler]. */
private function routes(): array
{
    return [
        'list'   => ['GET',    fn (Request $r) => $this->success('Files loaded.', $this->fileService->listFiles())],
        'read'   => ['GET',    $this->read(...)],
        'write'  => ['POST',   $this->write(...)],
        'delete' => ['DELETE', $this->delete(...)],
        'upload' => ['POST',   $this->upload(...)],
    ];
}

// in handle():
$routes = $this->routes();
[$method, $handler] = $routes[$action]
    ?? throw new UnsupportedActionException($action, array_keys($routes));

if ($request->getMethod() !== $method) {
    throw new MethodNotAllowedException($action, $method, $request->getMethod());
}

return $handler($request);
